-- =============================================================================
-- Atlas SMR: France 2030 Objectif 1 project funding and lead partners
-- =============================================================================
-- legacy_source 'f2030_obj1_funding_november_2026'. Researched 8 Nov 2026 from
-- official press kits (info.gouv.fr, Dec 2022 waste-call laureates; Mar 2024
-- 'Nucléaire de demain'), company releases and trade press. Many sources were
-- read only as search extracts: grant descriptions carry a confidence level and
-- '[to verify]' marks amounts not confirmed against an opened official page.
-- Full research with quotes: data/atlas_smr/project_funding.json.
-- Call totals: waste call (Bpifrance with Andra) 40 laureates, €71.7M State aid;
-- reactors call phase 1: 11 laureates, €129.8M (+€18.9M CEA support, Nov 2023).
-- No per-project amounts are published for 36 of the 53 projects.
-- Applied 8 Nov 2026; grant descriptions were lightly condensed when applied.
-- =============================================================================
CREATE TEMP TABLE s_proj AS SELECT * FROM json_populate_recordset(NULL::record, $j$[{"slug": "france-2030-obj1-anais", "summary": "Transportable, low-dose active neutron interrogation unit in a self-contained container to measure fissile mass (U, Pu) in waste packages. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-d-perle", "summary": "Pilot plant to purify uranium-contaminated perfluoropolyether lubricants that currently have no waste route. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-ds-demantelement-et-services", "first": "2022-12-09"}, {"slug": "france-2030-obj1-dnat", "summary": "Opens a new secure route to take spent French sealed radioactive sources as waste when they cannot go to Andra's existing surface repositories as sources. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": null, "first": "2022-12-09"}, {"slug": "france-2030-obj1-dream-scanner", "summary": "3D imaging system to characterise radioactivity of waste packages more precisely, avoiding over-classification of packages. Lead partner: Damavan Imaging. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "damavan-imaging", "first": "2022-12-09"}, {"slug": "france-2030-obj1-epona", "summary": "Lab-scale demonstration of laser isotope separation (SILVA route) to purify palladium from La Hague fission products of long-lived Pd-107. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-etis", "summary": "Fast, precise elemental measurement approach (complementing nuclear measurement) to clear materials for recycling, tested on Orano metal and soil valorisation projects. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-demantelement", "first": "2022-12-09"}, {"slug": "france-2030-obj1-isac", "summary": "Feasibility study of transmuting minor actinides (mainly americium) in molten-salt reactors to reduce ultimate waste. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: €14M [to verify].", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-kryptrap", "summary": "Separating and trapping krypton from off-gases of fuel-cycle facilities. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-maeva2", "summary": "Using depleted uranium to make high-performance concretes (non-energy valorisation). Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-chimie-enrichissement", "first": "2022-12-09"}, {"slug": "france-2030-obj1-pach3", "summary": "Multi-barrier low-outgassing packages for tritiated waste that has no disposal route. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-pallas", "summary": "Experimental platform to test monitoring solutions for radioactive waste packages inside storage cells. Lead partner: IRSN. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "irsn", "first": "2022-12-09"}, {"slug": "france-2030-obj1-providence", "summary": "Technology bricks and process knowledge to optimise DEM&MELT, an in-can thermal treatment/vitrification tool for intermediate-to-high-level waste. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-recyclage", "first": "2022-12-09"}, {"slug": "france-2030-obj1-regain", "summary": "Alternative to compacting fuel hulls: successive decontamination steps to cut their radiological source term and the volume of ultimate (MA-VL) waste. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-support", "first": "2022-12-09"}, {"slug": "france-2030-obj1-rpn2", "summary": "Melting and recycling very-low-level radioactive lead for reuse inside and outside the nuclear industry. Lead partner: Fonderie Lemer. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "fonderie-lemer", "first": "2022-12-09"}, {"slug": "france-2030-obj1-rtg", "summary": "Autonomous, wireless power source for Cigéo cell-monitoring sensors over the ~100-year operating life. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-demantelement", "first": "2022-12-09"}, {"slug": "france-2030-obj1-self", "summary": "Dissolving reactive metallic waste in molten hydroxide salts and re-precipitating it in a less hydrogen-generating form for conditioning. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-demantelement", "first": "2022-12-09"}, {"slug": "france-2030-obj1-smetana", "summary": "Optimising treatment of spent MOX fuel from first recycling and improving knowledge on fast-reactor fuel fabrication for multi-recycling. Lead partner: EDF. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "edf", "first": "2022-12-09"}, {"slug": "france-2030-obj1-solveris", "summary": "Industrial remediation of contaminated sites using GeoMelt in-situ vitrification of soils and buried waste. Lead partner: Safe Technologies. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": null, "first": "2022-12-09"}, {"slug": "france-2030-obj1-spatial", "summary": "Full spatial/energy mapping of reactivity at start-up of accelerator-driven subcritical reactors aimed at transmuting long-lived fission products. Lead partner: CNRS. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cnrs", "first": "2022-12-09"}, {"slug": "france-2030-obj1-tbatt-diamond", "summary": "20-year beta-voltaic micro-batteries using tritium recovered from nuclear waste in a synthetic diamond cell. Lead partner: DiamFab. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "diamfab", "first": "2022-12-09"}, {"slug": "france-2030-obj1-cimboost", "summary": "Continuous cementation process for fine-grained low/intermediate-level radioactive waste. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-demantelement", "first": "2022-12-09"}, {"slug": "france-2030-obj1-d-clic", "summary": "Know-how for managing long-lived radionuclides under strict release limits; could give routes for orphan wastes (e.g. solid traps) or inland reprocessing plants. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-demwaste", "summary": "Device to sort and segregate nuclear waste in a storage room or outdoor area before human intervention, anticipating final conditioning. Lead partner: DEMBoost. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "demboost", "first": "2022-12-09"}, {"slug": "france-2030-obj1-ecclor", "summary": "New route for radiocontaminated organic liquids: decontaminating 3D-printed mineral filters plus plasma-torch destruction. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-ecolas", "summary": "Laser surface-decontamination technology to downgrade operating/dismantling waste from 'rich' to 'poor' (glovebox decontamination at Orano Melox). Lead partner: Meliad. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "meliad", "first": "2022-12-09"}, {"slug": "france-2030-obj1-esop", "summary": "Diluent-free extractant system for U/Pu recovery in reprocessing to reduce effluents and fire risk. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-mirage", "summary": "Micro/millifluidic tool platform to speed development of spent-fuel recycling processes. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-moma", "summary": "Method to verify homogeneity of very-low-activity materials so sampling-based release controls are representative. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-demantelement", "first": "2022-12-09"}, {"slug": "france-2030-obj1-mosarwaste", "summary": "Describes, quantifies and assesses treatment, conditioning, storage and disposal impact of waste streams from a chloride molten-salt actinide-burner reactor. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-padawann", "summary": "Feasibility of a pulsed-laser process to decontaminate tritiated parts and dust. Lead partner: Université de Rouen Normandie (CORIA lab). Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: €1.9M [to verify].", "lead": "universite-de-rouen-normandie", "first": "2022-12-09"}, {"slug": "france-2030-obj1-porthos", "summary": "Process to produce, purify and condition thorium tetrachloride (ThCl4) for future Pu-Th fuels. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-support", "first": "2022-12-09"}, {"slug": "france-2030-obj1-prepac", "summary": "Recovering critical metals (Ru, Tc, Mo, Rh, Pd) in reprocessing plants to widen operating margins, cut waste and reuse the metals. Lead partner: CEA. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cea", "first": "2022-12-09"}, {"slug": "france-2030-obj1-r2ds", "summary": "Industrial robotics for retrieving and sorting nuclear waste in hostile environments. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-recyclage", "first": "2022-12-09"}, {"slug": "france-2030-obj1-rad2glass", "summary": "Industrial GeoMelt vitrification of radium-bearing low-level long-lived (FA-VL) waste for final disposal. Lead partner: Waste2Glass. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: €0.63M [to verify].", "lead": "waste2glass", "first": "2022-12-09"}, {"slug": "france-2030-obj1-simb-ad", "summary": "Method (Monte-Carlo plus real-time CMOS neutron detection) to determine pure-beta-emitter activity in cyclotron materials and shielding at dismantling. Lead partner: CNRS. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "cnrs", "first": "2022-12-09"}, {"slug": "france-2030-obj1-procer", "summary": "Pilot line and full-scale production of ceramic over-packs for high-level waste disposal. Lead partner: Bernardaud. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "bernardaud", "first": "2022-12-09"}, {"slug": "france-2030-obj1-trefle2", "summary": "Finer filtration system for effluents from nuclear-sector laundries. Lead partner: Nuvia. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "nuvia-protection", "first": "2022-12-09"}, {"slug": "france-2030-obj1-trtap", "summary": "Deploying plasma-torch thermal treatment to vitrify waste. Lead partner: Orano. Call: France 2030 « Solutions innovantes pour la gestion des matières et déchets radioactifs » (Bpifrance with Andra, laureates Dec 2022). State aid: not published per project.", "lead": "orano-demantelement", "first": "2022-12-09"}, {"slug": "france-2030-obj1-mrrep", "summary": "Studies and develops technical options for multi-recycling nuclear materials in today's pressurised-water reactors, while advancing fast-reactor fuel-cycle technologies. Lead partner: Orano. France 2030 nuclear action « Confirmer la faisabilité du multi-recyclage en réacteurs à eau pressurisée (MRREP) » (dedicated action, not a competitive call); operator: Bpifrance. State aid: €19M.", "lead": "orano-recyclage", "first": "2024-03-21"}, {"slug": "france-2030-obj1-projet-de-developpement-dune-plateforme-de-recherche-sur-les-performances-en-surete-des-systemes-passifs", "summary": "PASTIS (Passive Systems Thermohydraulic Investigations for Safety): an experimental platform to build the knowledge needed to assess passive safety systems used in most SMR designs, incl. NUWARD. Lead partner: IRSN (now ASNR). France 2030 nuclear action « Soutenir les efforts d'innovation de la filière par le déploiement d'outils de recherche performants et rénovés » – project PASTIS; operator: ANR (per IRSN project page: State aid managed by ANR, ref. ANR-22-PAST-0001). State aid: €9M.", "lead": "asnr", "first": "2024-03-21"}, {"slug": "france-2030-obj1-val-m2-tcn", "summary": "Probably the EDF Technocentre: an industrial site (planned at Fessenheim) to recycle very-low-level (TFA) radioactive metals. Lead partner: EDF (probable). France 2030 nuclear action « Développer des solutions innovantes pour la gestion des matières et déchets radioactifs » – project « Technocentre » (dedicated award, outside the 40-laureate call); operator: Bpifrance. State aid: €18.5M [to verify].", "lead": "edf", "first": "2024-03-21"}, {"slug": "france-2030-obj1-taranis", "summary": "Inertial-confinement laser fusion: aims to show economic viability of high-gain D-T fusion and develop an integrated ~1000 MWth reactor concept. Lead partner: GenF. France 2030 call n°1 « Réacteurs nucléaires innovants » (France 2030); operator: Bpifrance, with CEA (APNI) support. State aid: €3.5M [to verify].", "lead": "genf", "first": null}, {"slug": "france-2030-obj1-naarea-fce-2030", "summary": "Lead partner: Naarea. Call: France 2030 « Réacteurs nucléaires innovants » (Bpifrance). State aid: €10M [to verify].", "lead": "naarea", "first": null}, {"slug": "france-2030-obj1-newcleo-lfr-30-mwe", "summary": "Lead partner: newcleo. Call: France 2030 « Réacteurs nucléaires innovants » (Bpifrance). State aid: €19M [to verify].", "lead": "newcleo", "first": null}, {"slug": "france-2030-obj1-gta", "summary": "Lead partner: Jimmy Energy SAS. Call: France 2030 « Réacteurs nucléaires innovants » (Bpifrance). State aid: €32M (phase 1), €40M (phase 2).", "lead": "jimmy-energy", "first": "2023-11-27"}, {"slug": "france-2030-obj1-calogena", "summary": "Lead partner: Calogena (Groupe Gorgé). Call: France 2030 « Réacteurs nucléaires innovants » (Bpifrance). State aid: €5.2M (phase 1) [to verify], €48M (phase 2).", "lead": "calogena", "first": "2023-11-27"}, {"slug": "france-2030-obj1-rf01", "summary": "Lead partner: Renaissance Fusion SAS. Call: France 2030 « Réacteurs nucléaires innovants » (Bpifrance). State aid: €10M.", "lead": "renaissance-fusion", "first": "2023-11-27"}, {"slug": "france-2030-obj1-hexana", "summary": "Lead partner: Hexana. Call: France 2030 « Réacteurs nucléaires innovants » (Bpifrance). State aid: €10M [to verify].", "lead": "hexana", "first": "2023-11-27"}, {"slug": "france-2030-obj1-blue-capsule", "summary": "Lead partner: Blue Capsule (consortium with Egis Nucléaire and CEA). Call: France 2030 « Réacteurs nucléaires innovants » (Bpifrance). State aid: €10M [to verify].", "lead": "blue-capsule-technology", "first": "2023-11-27"}, {"slug": "france-2030-obj1-one", "summary": "Lead partner: Otrera Nuclear Energy (Otrera New Energy). Call: France 2030 « Réacteurs nucléaires innovants » (Bpifrance). State aid: not published per project.", "lead": "otrera", "first": "2023-11-27"}, {"slug": "france-2030-obj1-stellarium", "summary": "Lead partner: Stellaria (consortium with Orano and CEA). Call: France 2030 « Réacteurs nucléaires innovants » (Bpifrance). State aid: €10M.", "lead": "stellaria", "first": "2024-03-21"}, {"slug": "france-2030-obj1-proxima", "summary": "Lead partner: Thorizon (consortium with Orano and CEA, plus academic partners). Call: France 2030 « Réacteurs nucléaires innovants » (Bpifrance). State aid: €10M.", "lead": "thorizon", "first": "2024-03-21"}, {"slug": "france-2030-obj1-nuward", "summary": "EDF group's NUWARD small modular reactor. Lead partner: Nuward (EDF subsidiary). Direct State aid under France 2030, approved by the European Commission on 26 April 2024 (separate from the innovative-reactors call). State aid: €300M.", "lead": "nuward", "first": "2024-04-26"}]$j$) AS (slug text, summary text, lead text, first text);
UPDATE projects p SET summary=s.summary, first_evidence_date=COALESCE(s.first::date, p.first_evidence_date), updated_at=NOW() FROM s_proj s WHERE p.slug=s.slug;

UPDATE project_links pl SET role='lead' FROM s_proj s JOIN projects p ON p.slug=s.slug JOIN organizations o ON o.slug=s.lead
WHERE pl.project_id=p.id AND pl.organization_id=o.id;

